namespace RealEstatePro\Gating;defined('ABSPATH')||exit;
final class Gating{public function register():void{add_filter('the_content',[$this,'content'],20);}public function tier(int $uid=0):string{$t=get_user_meta($uid?:get_current_user_id(),'re_pro_customer_tier',true);return in_array($t,['free','pro','vip'],true)?$t:'free';}public function allowed(string $required,int $uid=0):bool{$r=['free'=>0,'pro'=>1,'vip'=>2];return ($r[$this->tier($uid)]??0)>=($r[$required]??0);}public function content(string $content):string{if(!is_singular('property')||!in_the_loop())return $content;$need=get_post_meta(get_the_ID(),'visibility_level',true)?:'free';if($this->allowed($need))return $content;return '<div class="re-pro-paywall"><div class="re-pro-blur">'.wp_kses_post($content).'</div><div class="re-pro-upgrade">برای مشاهده جزئیات کامل، اشتراک خود را ارتقا دهید.</div></div>';}}